-- 3/4/5-way multi-port batch: Series 30, 30M, 36, F35, F51, F52 (quote-only).
-- GO splits each series into its own batch. Series 33 already exists (not included).

-- ===== Series 30 (81 products, quote-only Price NULL) =====
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series 30')
    INSERT INTO Categories (Name, Description, BodyMaterial, SeatMaterial, Design, Approvals, KeyFeatures)
    VALUES (N'Series 30', N'The Mars Series 30 is a 3-way/4-way flanged trunnion-mounted ball valve rated ANSI Class 150/300 and PN16/40, full port, with L/T/X-port ball, sizes 1 1/2" to 12". CF8M or WCB body with PTFE/RTFE seats.', N'CF8M / WCB', N'PTFE / RTFE', N'Three/Four-Way, Flanged, Trunnion, Full Port', NULL, N'3-way / 4-way flanged trunnion design
Full port
Flange ratings: ANSI #150/#300, PN16/40
Ball configuration: L port, T port, X port
CF8M / WCB body
PTFE / RTFE seats
Size 1 1/2" to 12"');
GO
DECLARE @SeriesName nvarchar(100) = N'Series 30';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);
INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'Flange Rating'),(N'Size'),(N'Ball Configuration')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);
INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'Flange Rating',0),(N'Size',1),(N'Ball Configuration',2)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);
