-- ===== Series 36 (128 products, quote-only Price NULL) =====
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series 36')
    INSERT INTO Categories (Name, Description, BodyMaterial, SeatMaterial, Design, Approvals, KeyFeatures)
    VALUES (N'Series 36', N'The Mars Series 36 is a 3-way/4-way ball valve rated ANSI Class 150/300 and PN16/40 (1000 PSI max), full or reduced port, with L/T/I/X-port ball, in flanged, threaded, socket-weld or butt-weld ends, sizes 1/4" to 12". CF8M or WCB body with PTFE/RTFE seats.', N'CF8M / WCB', N'PTFE / RTFE', N'Three/Four-Way, Full & Reduced Port', NULL, N'3-way / 4-way design
Full port & reduced port
Ball configuration: L port, T port, I port, X port
Ends: Flanged, Threaded, Socket Weld, Butt Weld
ANSI Class 150/300, PN16/40 (1000 PSI max)
CF8M / WCB body
PTFE / RTFE seats
Size 1/4" to 12"');
GO
DECLARE @SeriesName nvarchar(100) = N'Series 36';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);
INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'End Connection'),(N'Size'),(N'Ball Configuration')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);
INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'End Connection',0),(N'Size',1),(N'Ball Configuration',2)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);
