-- ===== Series F51 (96 products, quote-only Price NULL) =====
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series F51')
    INSERT INTO Categories (Name, Description, BodyMaterial, SeatMaterial, Design, Approvals, KeyFeatures)
    VALUES (N'Series F51', N'The Mars Series F51 is a 3-way/4-way direct-mount fire-safe ball valve rated 3000 PSI, full port, with L/T/X/I-port ball, in threaded, socket-weld or butt-weld ends, sizes 1/4" to 2". CF8M or WCB body (Hastelloy C, Alloy 20, Super Duplex or Monel on request) with TFM4215/Peek seats (cavity filler seat on request).', N'CF8M / WCB (special alloys on request)', N'TFM4215 / Peek', N'Three/Four-Way, Direct Mount, Fire-Safe, Full Port, High Pressure', N'Fire-Safe', N'3-way / 4-way direct mount fire-safe design
Full port
Rated 3000 PSI
Ball configuration: L port, T port, X port, I port
Ends: Threaded, Socket Weld, Butt Weld
CF8M / WCB body (special alloys on request)
TFM4215 / Peek seats (cavity filler on request)
Size 1/4" to 2"');
GO
DECLARE @SeriesName nvarchar(100) = N'Series F51';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);
INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'End Connection'),(N'Size'),(N'Ball Configuration')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);
INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'End Connection',0),(N'Size',1),(N'Ball Configuration',2)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);
