  (N'VF52-ANSI-1500-2IN-I',N'Flange Rating',N'ANSI #1500'),(N'VF52-ANSI-1500-2IN-I',N'Size',N'2"'),(N'VF52-ANSI-1500-2IN-I',N'Ball Configuration',N'I port'),
  (N'VF52-ANSI-1500-2IN-X',N'Flange Rating',N'ANSI #1500'),(N'VF52-ANSI-1500-2IN-X',N'Size',N'2"'),(N'VF52-ANSI-1500-2IN-X',N'Ball Configuration',N'X port')
) AS v(PartNumber, FilterName, Value) ON v.PartNumber = p.PartNumber
JOIN Filters f ON f.Name = v.FilterName WHERE p.CategoryId=@CategoryId;
SELECT N'Series F52' AS Series, COUNT(*) AS Products FROM CatalogProducts WHERE CategoryId=@CategoryId;
GO
